// Voice packs: one bundled offline pack per UI language — zh is the CosyVoice
// voice longhua_v3.1, the other languages use Microsoft Edge neural voices
// (generated by scripts/gen_voices_edge.py). The pack of the selected language
// can be replaced with the user's own recordings (stored in the user dir,
// which always takes precedence over the bundled dir).
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { CUES, CUE_KEY_RE } from "../web/js/core/cues.js";
import { PACK_LANGS, cueText } from "../web/js/core/cue_texts.js";

export class TTSError extends Error {}

/** zh ships exactly one CosyVoice voice; every other language is edge@<lang>. */
const ZH_VOICE = "longhua_v3.1";
const dirName = (lang) => (lang === "zh" ? `${ZH_VOICE}@zh` : `edge@${lang}`);

/** Same digest as the generators (electron side and gen_voices_edge.py) so
 *  their packs are reused as-is. NOTE: the dir component keeps the historical
 *  value ("longhua_v3.1", not "longhua_v3.1@zh") so existing zh manifests
 *  stay valid after the directory rename. */
export const digest = (lang, text) => createHash("sha1")
  .update(`${lang === "zh" ? "qwen-audio-3.1-tts-flash" : "msedge-neural"}|${lang === "zh" ? ZH_VOICE : `edge@${lang}`}|${text}`)
  .digest("hex").slice(0, 16);

const MAX_CUE_BYTES = 10 * 1024 * 1024;

/** Fold a filename / cue text for tolerant matching ("左冲拳.mp3" -> "左冲拳"). */
const norm = (s) => String(s).toLowerCase().replace(/[\s_\-.,:;!?！？。，、：；"'"'（）()\[\]]/g, "");

export class VoicePacks {
  /** @param userDir    writable dir for user-recorded packs
   *  @param bundledDir read-only dir shipped with the app */
  constructor(userDir, bundledDir) {
    this.userDir = userDir;
    this.bundledDir = bundledDir;
  }

  #manifest(dir) {
    const p = join(dir, "manifest.json");
    try {
      return existsSync(p) ? JSON.parse(readFileSync(p, "utf8")) : {};
    } catch {
      return {};
    }
  }

  /** Path of an up-to-date cue file (user pack first), or null. */
  cuePath(lang, key) {
    if (!PACK_LANGS.includes(lang) || !CUE_KEY_RE.test(key)) return null;
    const want = digest(lang, cueText(lang, key));
    for (const root of [this.userDir, this.bundledDir]) {
      if (!root) continue;
      const file = join(root, dirName(lang), `${key}.mp3`);
      if (this.#manifest(join(root, dirName(lang)))[key] === want && existsSync(file)) return file;
    }
    return null;
  }

  readyKeys(lang) {
    return Object.keys(CUES).filter((k) => this.cuePath(lang, k));
  }

  /** Per-language pack status: { <lang>: { ready, total, custom } }. */
  status() {
    const total = Object.keys(CUES).length;
    return Object.fromEntries(PACK_LANGS.map((lang) => [
      lang,
      {
        ready: this.readyKeys(lang).length,
        total,
        custom: !!this.userDir && existsSync(join(this.userDir, dirName(lang))),
      },
    ]));
  }

  /** Per-cue status of one language for the settings UI. */
  cueInfo(lang) {
    if (!PACK_LANGS.includes(lang)) throw new TTSError(`不支持的语言 ${lang}`);
    return Object.keys(CUES).map((key) => ({ key, custom: !!this.cuePath(lang, key) && this.#customHas(lang, key) }));
  }

  #customHas(lang, key) {
    return !!this.userDir && existsSync(join(this.userDir, dirName(lang), `${key}.mp3`));
  }

  /** Replace a single cue with the user's recording (shadows the bundled pack). */
  importCue(lang, key, bytes) {
    if (!PACK_LANGS.includes(lang)) throw new TTSError(`不支持的语言 ${lang}`);
    if (!CUE_KEY_RE.test(key) || !(key in CUES)) throw new TTSError(`未知台词 ${key}`);
    const buf = Buffer.from(bytes ?? []);
    if (!buf.length || buf.length > MAX_CUE_BYTES) throw new TTSError("音频文件为空或超过 10MB");
    const dir = join(this.userDir, dirName(lang));
    mkdirSync(dir, { recursive: true });
    const manifest = this.#manifest(dir);
    writeFileSync(join(dir, `${key}.mp3`), buf);
    manifest[key] = digest(lang, cueText(lang, key));
    writeFileSync(join(dir, "manifest.json"), JSON.stringify(manifest, null, 1));
    return true;
  }

  /**
   * Replace cues of one language with user recordings. Each file is matched
   * by name (without extension) against the cue key or the translated cue
   * text, then written into the user pack so it shadows the bundled one.
   * @returns {{ imported: number, missed: string[] }}
   */
  importCues(lang, files = []) {
    if (!PACK_LANGS.includes(lang)) throw new TTSError(`不支持的语言 ${lang}`);
    const byName = new Map();
    for (const key of Object.keys(CUES)) {
      byName.set(norm(key), key);
      byName.set(norm(cueText(lang, key)), key);
    }
    const dir = join(this.userDir, dirName(lang));
    mkdirSync(dir, { recursive: true });
    const manifest = this.#manifest(dir);
    const missed = [];
    let imported = 0;
    for (const { name, bytes } of files) {
      const base = String(name ?? "").replace(/\.[^.]+$/, "");
      const key = byName.get(norm(base));
      if (!key) {
        missed.push(base);
        continue;
      }
      const buf = Buffer.from(bytes ?? []);
      if (!buf.length || buf.length > MAX_CUE_BYTES) {
        missed.push(base);
        continue;
      }
      writeFileSync(join(dir, `${key}.mp3`), buf);
      manifest[key] = digest(lang, cueText(lang, key));
      imported++;
    }
    if (imported) writeFileSync(join(dir, "manifest.json"), JSON.stringify(manifest, null, 1));
    else if (!Object.keys(manifest).length) rmSync(dir, { recursive: true, force: true });
    return { imported, missed };
  }

  /** Drop the user pack of one language: the bundled pack shines again. */
  reset(lang) {
    if (!PACK_LANGS.includes(lang)) throw new TTSError(`不支持的语言 ${lang}`);
    rmSync(join(this.userDir, dirName(lang)), { recursive: true, force: true });
    return true;
  }
}
